{
  "architect_scope": "one-R50-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "The active contract-locked relay preserves upstream conformance authority while isolating downstream behavioral authority, creating path dependence that prevents coherent whole-policy reconsideration.",
    "causal_change": "Replace the authority-preserving edge with an authority-extinguishing supersession edge: the complete executable predecessor remains visible as evidence, but none of its decisions remain binding and the terminal call assumes indivisible whole-artifact responsibility.",
    "expected_effect": "Removing inherited authority should permit coordinated changes in scan resistance and phase-shift adaptation while retaining executable predecessor visibility for conformance evidence.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "authority-extinguishing whole-artifact supersession across an executable-closure edge",
    "before": "The executable closure transfers an immutable contract boundary while delegating only behavior-semantic revision.",
    "after": "The executable closure transfers with full evidentiary visibility but zero surviving normative authority, and the terminal call supersedes it as one indivisible artifact.",
    "why_structural": "The mutation changes the edge's state-transition and authority semantics from partial preservation to complete authority extinction and supersession without changing the sequential call count or external-evidence visibility."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "Upstream contract decisions must remain normatively binding downstream.",
      "Contract conformance and behavior semantics should belong to separate sequential authorities."
    ],
    "forbidden_inherited_mechanism": "immutable upstream contract locking with behavior-only downstream revision",
    "independent_replacement_principle": "Preserve the complete executable predecessor only as visible evidence while extinguishing its authority and requiring indivisible whole-artifact supersession.",
    "changed_behavioral_dimensions": [
      "scan resistance",
      "phase-shift adaptation"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Executable-Foil Supersession Relay",
    "organization": "two-call sequential lineage with one authority-extinguishing executable edge",
    "information_flow": "The first call receives all common evidence and emits one complete executable closure as a visible structural foil. The terminal call consumes that closure and the same public non-anchor evidence available in the champion terminal position; the edge extinguishes every inherited authority partition, leaving the predecessor visible only as evidence while the terminal call assumes unified responsibility and emits one policy.",
    "stages": [
      {
        "id": "supersession_relay",
        "mode": "sequential",
        "calls": [
          {
            "id": "construct_executable_foil",
            "role": "executable-foil authority",
            "objective": "Form exactly one complete executable policy closure from the supplied evidence and expose the entire artifact for downstream examination without granting any of its authority permanent survival.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "executable_policy_closure"
          },
          {
            "id": "supersede_visible_foil",
            "role": "indivisible supersession authority",
            "objective": "Consume construct_executable_foil and the supplied public evidence, treat the predecessor solely as visible evidence, extinguish its inherited normative authority, assume unified contract-and-behavior responsibility, and emit one complete policy.",
            "inputs": [
              "construct_executable_foil",
              "task",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "supersede_visible_foil"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
